script:
frappe.ui.form.on('Asset', {
    refresh: function(frm) {

        // Remove default Scrap button
        frm.page.remove_inner_button('Scrap Asset', 'Manage');

        // Add your custom option
        frm.page.add_inner_button('Mark as Damaged', function() {

            frappe.new_doc('Unserviceable or Damaged', {
                asset: frm.doc.name,
                asset_name: frm.doc.asset_name,
                asset_category: frm.doc.asset_category,

            });

        }, 'Manage');
    }
});

frappe.ui.form.on('Asset', {
    item_code: function(frm) {
        if (frm.doc.item_code) {
            // We reach into the Item record to find the specific series you generated
            frappe.db.get_value('Item', frm.doc.item_code, 'asset_naming_series', (r) => {
                if (r && r.asset_naming_series) {
                    // We set the Asset's standard naming_series field
                    frm.set_value('naming_series', r.asset_naming_series);
                }
            });
        }
    }
});

frappe.ui.form.on('Item', {
    refresh: function(frm) {
        // 1. Check if the user is an Administrator or has the System Manager role
        if (frappe.session.user === "Administrator" || frappe.user_roles.includes("System Manager")) {

            // For Admin: Make the field editable and do NOT force a value
            frm.set_df_property('asset_naming_series', 'read_only', 0);

        } else {

            // For Regular Users: Run your original logic
            if (frm.is_new() || !frm.doc.asset_naming_series) {

                frappe.db.get_value('Employee', {'user_id': frappe.session.user}, 'custom_lab_name', (r) => {
                    if (r && r.custom_lab_name) {
                        const lab_map = {
                            "Central Soil Analytical Lab, Parottukonam": "TVM",
                            "Soil and Plant Health Clinic, Pathanamthitta":"PTA",
                            "Regional Soil Analytical Laboratory Alappuzha": "ALP",
                            "Regional Soil Analytical Laboratory Thrissur": "TSR",
                            "Regional Soil Analytical Laboratory Kozhikode": "KKD",
                            "Soil and Plant Health Clinic, Kasaragod": "KSD",
                            "Hi-Tech Soil Analytical Lab WYD": "WYD"
                        };

                        let short_code = lab_map[r.custom_lab_name];
                        if (short_code) {
                            let final_series = "ASS-" + short_code + "-.####";
                            frm.set_value('asset_naming_series', final_series);
                        }
                    }
                });
            }

            // Lock it for regular users so they can't change their assigned lab code
            frm.set_df_property('asset_naming_series', 'read_only', 1);
        }
    }
});

frappe.ui.form.on('Asset', {
    onload: function(frm) {

        frappe.db.get_value(
            "Employee",
            { user_id: frappe.session.user },
            "custom_lab_name",
            function(r) {

                if (r && r.custom_lab_name) {

                    frm.set_query("item_code", function() {
                        return {
                            filters: {
                                custom_lab: r.custom_lab_name
                            }
                        };
                    });

                }

            }
        );

    }
});

frappe.ui.form.on('Stock Entry', {
    onload_post_render: function(frm) {

        // Remove entire "Create" dropdown
        frm.page.clear_inner_toolbar();

        // Remove "Get Items From" button
        frm.page.remove_inner_button("Material Request", "Get Items From");
        frm.page.remove_inner_button("Purchase Order", "Get Items From");

    }
});
